int
score(warnum)
  int     warnum;
{
  int     surv, accu = 0;
  long    res;

  for (surv = 1; surv <= warriors; ++surv) {
    set_reg('S', (long) surv);
    if (eval_expr(SWITCH_eq, &res) < OK_EXPR)
      return INT_MIN;                /* hopefully clparse will catch errors
                                 * earlier */
    else
      accu += warrior[warnum].score[surv - 1] * res;
  }
  return accu;
}

